parsers/code/java/src/lib.rs (~40 LOC non-test):
```rust
/// A Java top-level type belongs to its package (its directory), not its file: drop the file-stem
/// segment the engine's path_to_qname puts last. `src::main::java::Foo` -> `src::main::java`; a
/// file at the repo root (`Foo`) -> "".
fn type_scope(module_qname: &str) -> &str { module_qname.rsplit_once("::").map_or("", |(p, _)| p) }
fn scoped(scope: &str, name: &str) -> String { if scope.is_empty() { name.to_string() } else { format!("{scope}::{name}") } }
```
