code-domain/src/lib.rs, inside `pub mod endpoint` (~60 LOC + unit tests):
```rust
/// The ONE canonical path form for ROUTE / ENDPOINT qnames: exactly the input when it already
/// starts with '/', starts with a `${` base placeholder, is empty, or is `<unresolved>`;
/// otherwise abs_path(p) (`api/users` -> `/api/users`). Paths that already start with '/' are
/// returned byte-identical, so no correct qname moves.
pub fn canonical_http_path(p: &str) -> std::borrow::Cow<'_, str>;
pub fn is_canonical_http_path(p: &str) -> bool;              // the same exemptions; the census uses it
pub fn route_qname(method: &str, path: &str) -> String;      // "<METHOD> <canonical>" (legacy shape)
pub fn route_path_qname(path: &str) -> String;               // "route:<canonical>" (go / ts_routes shape)
pub fn endpoint_qname(method: &str, path: &str) -> String;   // "endpoint:<METHOD>:<canonical>"
