pub enum MoveTier { Declared, Identical, SameName }
pub enum Rebind { Exact(NodeId), Moved { id: NodeId, tier: MoveTier }, Ambiguous(Vec<NodeId>), Orphan }
pub struct FileMove { pub old_path: String, pub new_path: String, pub tier: MoveTier }
