```rust
/// A Scala top-level type belongs to its package (its directory, LB.2's rule), not its file:
/// drop the file-stem segment path_to_qname put last. `src::main::scala::shop::Widget` -> `src::main::scala::shop`;
/// a root-level file (`Widget`) -> "".
fn type_scope(module_qname: &str) -> &str { module_qname.rsplit_once("::").map_or("", |(p, _)| p) }
fn scoped(scope: &str, name: &str) -> String { if scope.is_empty() { name.to_string() } else { format!("{scope}::{name}") } }
```
