/// A non-code file's MODULE qname (LB.9a): the directories `::`-joined plus the FULL file name.
/// path_to_qname drops the extension, which is right for code (imports name the stem) but lets
/// `user.proto` share `api::user` with `user.go`, and `Dockerfile.prod` fold into `Dockerfile`.
pub(crate) fn synthetic_module_qname(path: &str) -> String {
    let p = path.replace('\\', "/");
    match p.rsplit_once('/') { Some((dir, file)) => format!("{}::{file}", dir.replace('/', "::")), None => p }
}
