```rust
/// LB.13: which sibling a bare import binds when one graph holds several files of a stem (`util.ts` + `util.js`).
/// Keyed by the IMPORTER's extension; each list is that language's own resolution order. Only languages that import
/// FILES have one: Java / Kotlin import classes, Elixir aliases modules, Terraform modules are directories, and a
/// .cljc file loads a different sibling per platform. Empty = no rule: the import stays unresolved (counted).
pub fn same_stem_order(importer_ext: &str) -> &'static [&'static str] {
    match importer_ext {
        "ts" | "tsx" => &["ts", "tsx", "js", "jsx", "vue"],         // tsc: .ts .tsx (.d.ts), then .js .jsx under allowJs
        "js" | "jsx" | "vue" => &["js", "ts", "jsx", "tsx", "vue"], // Vite resolve.extensions default: .mjs .js .mts .ts .jsx .tsx
        "clj" => &["clj", "cljc"],                                 // Clojure RT.load: .clj before .cljc; never .cljs
        "cljs" => &["cljs", "cljc"],                               // ClojureScript: .cljs before .cljc; never .clj
        _ => &[],
    }
}
```
