/// Build-local: never stored in the SymbolTable.
#[derive(Default)]
pub(crate) struct SameStem { by_bare: BTreeMap<String, Vec<(String /*ext*/, NodeId)>>, module_ext: HashMap<NodeId, String>, stats: SameStemStats /* explicit, importer, unresolved */ }
pub(crate) fn same_stem_table(g: &RepoGraph) -> SameStem;
impl SameStem {
    /// `bare` = the stem-form qname an import resolved to (`src::util`). Explicit extension first (`./util.js`), else the
    /// first extension of same_stem_order(importer's ext) present. None when `bare` is not an ambiguous stem of this graph.
    pub(crate) fn pick(&mut self, bare: &str, explicit_ext: Option<&str>, importer: NodeId) -> Option<NodeId>;
    /// Dotted requires that do not carry the directory (`(:require [app.core])` -> `app::core`): the unique ambiguous stem
    /// equal to or ending in `::app::core`, then `pick`. Two matching stems -> None.
    pub(crate) fn pick_suffix(&mut self, path_qname: &str, importer: NodeId) -> Option<NodeId>;
    pub(crate) fn report(&self) // `[imports] same-stem picks: explicit={e} importer={i} unresolved={u}` when any attempt was made
}
```
