```rust
/// LB.10c: a bound out-of-line member's enclosing MODULE is its class's header, but its body still
/// sees its own file: a Bare name the generic chain missed is looked up in the defining file's lexical
/// scope (its namespace PACKAGE, then that file's MODULE). File-scoped PACKAGEs have their own file's
/// MODULE as parent, so the walk never leaves the defining file.
fn defining_scope_call(g: &RepoGraph, defining: &HashMap<NodeId, NodeId>, site: &CallSite) -> Option<NodeId> {
    let CallQualifier::Bare(name) = &site.qualifier else { return None };
    let mut scope = *defining.get(&site.from)?;
    loop {
        if let Some(hit) = g.symbols.module_symbols.get(&scope).and_then(|s| s.get(name)) { return Some(*hit); }
        if g.nav.kind_by_id.get(&scope) == Some(&node_kind::MODULE) { return None; }
        scope = *g.nav.parent_of.get(&scope)?;
    }
}
```
