```rust
// LB.14: a C# 11 `file` type is file-local in every namespace form. LB.7d scopes the compilation-unit
// ones by the file; a block-namespace one takes the same file scope, so two files' `file class
// Scratch` are two nodes and the qname survives a block -> file-scoped migration.
let file_scope = acc.module_qname.clone();  // once per visit_children call, only when a `file` type is met
