--- models/registry.ts ---
// Mongoose models: one named by a literal (the control), one by a variable.
import mongoose from "mongoose";

const userSchema = new mongoose.Schema({ name: String });
export const User = mongoose.model("User", userSchema);

export function register(modelName: string, schema: mongoose.Schema) {
  return mongoose.model(modelName, schema);
}

export const REGISTRY_LABEL = "Registry";

--- scripts/entity_needles.py ---
"""Scanner needle table: the strings are data, not models or tables."""

NEEDLES = ["mongoose.model(", "TableName:", "dynamodb.Table("]


def find_needle(text):
    for n in NEEDLES:
        at = text.find(n)
        if at >= 0:
            return at
    return None

--- app/models.py ---
from sqlalchemy.orm import declared_attr

from beanie import Document


class Order:
    __tablename__ = "orders"


class Base:
    @declared_attr
    def __tablename__(cls):
        return cls.__name__.lower()

    AUDIT_LABEL = "audit"


class Event(Document):
    class Settings:
        name = "events"


class Draft(Document):
    class Settings:
        name = collection_name()
        validate_on_save = "strict"

--- app/store.ts ---
// DynamoDB SDK v3: a table named by the environment, then a literal (the control).
import { DynamoDBClient, PutItemCommand } from "@aws-sdk/client-dynamodb";

const ddb = new DynamoDBClient({});

export async function saveOrder(id: string) {
  await ddb.send(new PutItemCommand({
    TableName: process.env.ORDERS_TABLE,
    Item: { id: { S: id }, status: { S: "pending" } },
  }));
}

export const sessionPut = { TableName: "sessions", Item: {} };

