--- svc/topics.ts ---
export const ORDERS_TOPIC = "orders";
export const PAYMENTS_TOPIC = "payments";

--- svc/bus.ts ---
import { Kafka } from "kafkajs";
import { ORDERS_TOPIC, PAYMENTS_TOPIC } from "./topics";

const kafka = new Kafka({ clientId: "svc", brokers: ["k:9092"] });
const producer = kafka.producer();
const consumer = kafka.consumer({ groupId: "svc" });

export async function publishOrder(order: { id: string }) {
  await producer.send({ topic: ORDERS_TOPIC, messages: [{ value: order.id }] });
}

export async function retryOrder(id: string) {
  await producer.send({ topic: "orders", messages: [{ value: id }] });
}

export async function listen() {
  await consumer.subscribe({ topic: PAYMENTS_TOPIC });
}

